parameters.jsCode:
const {action, taskId, prompt} = $json;
if (!['preview', 'create', 'status'].includes(action)) throw new Error('Choose preview, create or status.');
if (typeof taskId !== 'string') throw new Error('Keep taskId in quotes to preserve every character.');
const id = taskId.trim();
if (action === 'status') {
  if (!id || id === '.' || id === '..') throw new Error('Paste the task_id from your create receipt before checking status.');
  return {json:{action, taskId:id}};
}
if (action === 'create' && id) throw new Error('A task ID is already present. Choose status to check the existing render.');
if (typeof prompt !== 'string' || !prompt.trim()) throw new Error('Enter a text prompt for the shot.');
const body = {model:'MiniMax-H3', content:[{type:'text',text:prompt.trim()}], resolution:'768P', duration:5, ratio:'9:16'};
return {json:{action, body, estimatedUsdAtSampleRate:0.39, rateChecked:'2026-11-26'}};
